import sys

def solve():
    try:
        input_data = sys.stdin.read().split()
    except Exception:
        return

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        n = int(next(iterator))
        m = int(next(iterator))

        board = []
        for _ in range(n):
            row = []
            for _ in range(m):
                row.append(next(iterator))
            board.append(row)

        word = next(iterator)
    except StopIteration:
        return

    def dfs(r, c, index):
        if index == len(word):
            return True

        if r < 0 or r >= n or c < 0 or c >= m:
            return False

        if board[r][c] != word[index]:
            return False

        original_char = board[r][c]
        board[r][c] = '#'

        found = (dfs(r + 1, c, index + 1) or
                 dfs(r - 1, c, index + 1) or
                 dfs(r, c + 1, index + 1) or
                 dfs(r, c - 1, index + 1))

        board[r][c] = original_char
        return found

    found = False
    for i in range(n):
        for j in range(m):
            if dfs(i, j, 0):
                found = True
                break
        if found:
            break

    if found:
        print("true")
    else:
        print("false")

if __name__ == "__main__":
    solve()
